-- Expand the global drill library from 18 to 50 active templates.
-- Idempotent by title; preserves team-authored drills and existing templates.
insert into public.training_drills
(team_id,is_template,title,category,difficulty,role_tags,duration_minutes,objective,setup,steps,success_criteria,scoring_rubric,tags,archived)
select null,true,v.title,v.category,v.difficulty,v.role_tags,v.duration_minutes,v.objective,v.setup,v.steps,v.success_criteria,v.scoring_rubric,v.tags,false
from (values
('P1 Contact Call Sequence','communication','medium',array['P1 Primary Rusher'],15,'Report location, direction, certainty and changes in a consistent order.','Coach reads a map scenario; report verified details only.',array['Landmark first','Direction and approximate distance','Confirmed facts versus unknowns','What changed','One concise update'],'Five consecutive calls are accurate, brief and actionable.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p1','callouts']),
('P1 Readiness Confirmation','role','medium',array['P1 Primary Rusher','P2 Secondary Rusher'],15,'Confirm route, support readiness and fallback before a planned move.','Map walkthrough with paired checkpoints.',array['P1 states route and destination','P2 confirms support position','P3 reports map context','P4 confirms timing and fallback','P1 repeats the plan'],'All players understand the same route, role and fallback.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p1','p2','readiness']),
('P1 Information Prioritization','communication','advanced',array['P1 Primary Rusher'],15,'Separate decision-relevant information from duplicate or uncertain details.','Coach provides mixed map observations.',array['Sort confirmed and uncertain facts','Remove duplicates','Report priority first','State possible impact','Update only when facts change'],'IGL can repeat the key information and its uncertainty.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p1','information']),
('P1 Plan-Change Reporting','communication','advanced',array['P1 Primary Rusher'],15,'Report when new information makes the agreed plan outdated.','Replay paused before a route decision.',array['Name changed assumption','Report verified information','Explain route impact','Request IGL confirmation','Repeat revised instruction'],'Plan changes are shared before teammates act on outdated information.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p1','adaptability']),
('P1 Landmark Memory','positioning','beginner',array['P1 Primary Rusher'],10,'Use consistent map landmarks so teammates identify the same location.','Select six visible landmarks on a map.',array['Coach names a landmark','P1 describes two references','Teammate locates it','Compare interpretations','Repeat'],'At least five of six locations are identified consistently.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p1','map-awareness']),
('P1-P2 Shared Route Rehearsal','entry-trade','medium',array['P1 Primary Rusher','P2 Secondary Rusher'],15,'Ensure the pair understands the same route, support task and regroup condition.','Non-combat map walkthrough with paired checkpoints.',array['P1 explains route','P2 repeats support task','Both name a pause condition','IGL confirms fallback','Pair completes route and debriefs'],'P1 and P2 independently describe the same route and fallback.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p1','p2','coordination']),
('P2 Support Readiness Updates','backup','medium',array['P2 Secondary Rusher'],15,'Communicate availability and route status before each checkpoint.','Use map markers and a custom-room route.',array['Confirm current location','Confirm route understanding','Report visibility gap','State ready-to-move status','Update if readiness changes'],'IGL and P1 can correctly state P2''s status at each checkpoint.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p2','support']),
('P2 Two-Way Acknowledgement','communication','beginner',array['P2 Secondary Rusher'],10,'Replace assumptions with short, accurate confirmations.','Coach gives six instructions during a map walkthrough.',array['Listen fully','Repeat action and destination','Ask one clarification if needed','Confirm checkpoint completion','Avoid unrelated commentary'],'All six instructions are understood and completed correctly.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p2','communication']),
('P2 Pair Spacing Awareness','positioning','medium',array['P2 Secondary Rusher'],15,'Maintain the agreed support relationship along a planned route.','Use shared landmarks and visibility checkpoints.',array['Agree on separation reference','Move through route','Call when visibility is lost','Name regroup point','Review unclear updates'],'Pair maintains contact or reports separation promptly.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p2','spacing']),
('P2 Team Status Reporting','communication','beginner',array['P2 Secondary Rusher'],10,'Give relevant status updates without repeating unchanged information.','Use mock status cards or post-match screens.',array['Use agreed short vocabulary','Report relevant changes','Flag issues affecting plan','Confirm key update','Avoid duplicate calls'],'Relevant status changes are reported once and understood.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p2','status']),
('P2 Backup Caller Handover','igl','advanced',array['P2 Secondary Rusher','P4 Sniper + IGL'],15,'Maintain a consistent plan when the primary caller hands over.','Use three paused map scenarios.',array['Primary caller states plan and fallback','P2 repeats both','Coach signals handover','P2 gives next instruction','Primary caller resumes and confirms'],'Handover has no contradictory instruction or lost context.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p2','backup-igl']),
('P2 Support Review Notes','communication','beginner',array['P2 Secondary Rusher'],10,'Write evidence-based notes about support timing and awareness.','Review one short replay segment.',array['Record timestamp','Note whether update was useful','Identify missed update','Write measurable correction','Avoid judging only by outcome'],'One timestamped observation and one measurable correction are recorded.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p2','review']),
('P3 Map Scan Routine','positioning','medium',array['P3 Third Rusher / Flanker'],15,'Build a repeatable scan-and-report routine for map information.','Use a map image or paused replay.',array['Scan agreed sectors','Record visible facts only','Mark unknown areas','Report changes using landmarks','Repeat after scenario change'],'Relevant map changes are reported without presenting guesses as facts.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p3','map-awareness']),
('P3 Route Status Updates','flank','medium',array['P3 Third Rusher / Flanker'],15,'Keep the squad informed about route, checkpoint and regroup status.','Walk two alternate map routes without engagement objectives.',array['Name selected route','Give next checkpoint','Report route changes','State nearest regroup point','Confirm return to squad'],'Squad always knows P3''s route status and next checkpoint.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p3','flank']),
('P3 Information Priority Filter','communication','advanced',array['P3 Third Rusher / Flanker'],15,'Prioritize information that can change the team''s map decision.','Coach supplies useful, uncertain and duplicate observations.',array['Sort by urgency and certainty','Remove duplicates','Report priority first','State unknowns','Update when priority changes'],'Team receives the most decision-relevant facts first.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p3','information']),
('P3 Map Change Early Warning','rotation','advanced',array['P3 Third Rusher / Flanker'],15,'Notify the IGL when verified map changes affect the route.','Use a staged map-state timeline.',array['Track current checkpoint','Identify relevant change','Report source and landmark','Ask IGL to review route','Confirm new checkpoint'],'Relevant changes are shared before the team reaches the affected checkpoint.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p3','rotation']),
('P3 Regroup Landmark Discipline','positioning','medium',array['P3 Third Rusher / Flanker'],15,'Use a precise shared location when returning to the squad.','Choose three rally landmarks on a map.',array['IGL announces landmark','P3 repeats approach route','P3 reports arrival or delay','Request alternate point if needed','Confirm roster count'],'All players identify the same rally point without vague directions.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p3','regroup']),
('P3-P4 Information Sync','positioning','medium',array['P3 Third Rusher / Flanker','P4 Sniper + IGL'],15,'Combine local observations with the IGL''s wider map picture.','Two-source map scenario.',array['P3 reports nearby landmarks','P4 compares wider context','Mark conflicting details','IGL requests verification','Update shared map note'],'Verified information is shared and unknowns remain clearly marked.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p3','p4','map-awareness']),
('P3 Replay Route Annotation','positioning','beginner',array['P3 Third Rusher / Flanker'],15,'Annotate route, updates and regroup points for replay review.','Use one recorded match or map timeline.',array['Mark start and end checkpoints','Add update timestamps','Mark unreported changes','Identify missing regroup point','Write next-session target'],'Another teammate can follow the annotated route.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p3','replay']),
('P4 Five-Second Decision Brief','igl','advanced',array['P4 Sniper + IGL'],15,'Turn a changing map situation into one concise decision brief.','Coach presents a paused replay with limited information.',array['State verified situation','Name preferred team action','Give checkpoint or timing','State one fallback','Request acknowledgements'],'Team repeats action, timing and fallback after one brief.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p4','igl','decision']),
('P4 Confidence Labels','igl','medium',array['P4 Sniper + IGL'],15,'Make certainty explicit so assumptions are not repeated as facts.','Replay includes clear and incomplete visual information.',array['Label confirmed, likely or unknown','Do not overstate estimates','State what needs verification','Update label when evidence changes','Keep report concise'],'All notes consistently distinguish confirmed and uncertain information.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p4','igl']),
('P4 Route Option Comparison','rotation','advanced',array['P4 Sniper + IGL'],20,'Compare route options using consistent map factors and fallback planning.','Use a map with three possible routes.',array['List known zone and terrain facts','Compare distance and route complexity','State main trade-off','Choose and explain deciding factor','Define reconsideration trigger'],'Decision log records evidence, trade-off, route and fallback.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p4','rotation']),
('P4 Quiet Comms Window','communication','medium',array['P4 Sniper + IGL'],10,'Control voice traffic during a designated information window.','Map walkthrough with one caller and three reporters.',array['IGL opens information window','Players report new relevant facts','IGL summarizes','Players acknowledge once','Review interruptions and duplicates'],'No overlapping non-essential calls; important updates remain audible.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p4','comms']),
('P4 End-Zone Plan Explanation','endgame','advanced',array['P4 Sniper + IGL'],20,'Explain a final-zone plan with roles, landmarks and fallback.','Static end-zone map scenario.',array['Identify intended playable area','Name shared landmarks','Assign observation responsibilities','State movement trigger','State fallback and regroup point'],'Every player can repeat their responsibility and fallback.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p4','endgame']),
('P4 Decision Log Review','igl','medium',array['P4 Sniper + IGL'],15,'Evaluate decisions using information available at the time.','Pause a replay before the outcome is visible.',array['Write available information','Record call and purpose','Note uncertainty','View outcome afterwards','Separate process quality from result'],'Review avoids hindsight bias and records a fair decision rationale.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p4','review']),
('P4 Backup Caller Scenario','igl','advanced',array['P4 Sniper + IGL'],15,'Practise calm handover and restoration of caller responsibilities.','Use a map scenario with planned handover moments.',array['Primary states plan and fallback','Backup repeats both','Coach signals handover','Backup gives next instruction','Primary resumes and confirms'],'No conflicting instructions or loss of shared plan.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['p4','backup-igl']),
('Four-Player Callout Vocabulary','communication','beginner',array['All players'],15,'Create shared names for landmarks, directions and status updates.','Choose six map landmarks and a small glossary.',array['Each player describes landmarks','Compare ambiguous names','Agree on short phrase','Add terms to glossary','Run recall round'],'All four players use the same names for selected locations.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['squad','communication']),
('Information Acknowledgement Chain','communication','medium',array['All players'],15,'Ensure important calls are heard, understood and confirmed.','Scripted map scenario with one caller and three listeners.',array['Caller gives one instruction','Assigned players acknowledge','Caller checks missing response','Players report checkpoint completion','Repeat with changed instruction'],'Every instruction receives the correct acknowledgement and completion report.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['squad','comms']),
('Four-Player Map Landmark Quiz','positioning','beginner',array['All players'],15,'Build shared map language across all four players.','Prepare ten map screenshots or marked locations.',array['Show one location','Each player names landmark','Compare descriptions','Agree canonical callout','Repeat until consistent'],'At least eight of ten locations are described consistently.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['squad','map-awareness']),
('Rotation Checkpoint Confirmation','rotation','medium',array['All players'],15,'Keep all players synchronized around planned route checkpoints.','Use a map route with three named checkpoints.',array['IGL announces destination','Players confirm understanding','Each reports arrival','IGL updates next checkpoint','Team confirms regroup'],'All players report the same checkpoints in the correct order.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['squad','rotation']),
('Match Opening Role Check','role','beginner',array['All players'],10,'Start each match with clear responsibilities and a shared first checkpoint.','Use a short pre-match checklist.',array['P1 confirms information task','P2 confirms support task','P3 confirms map-awareness task','P4 confirms caller task','All repeat first checkpoint'],'Roles and first checkpoint are confirmed before the match.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['squad','roles']),
('Post-Match Timeline Reconstruction','squad-coordination','advanced',array['All players'],20,'Reconstruct a key sequence using timestamps and shared evidence.','Select a short replay segment.',array['Each player notes timestamps','Combine into one timeline','Verify conflicting recollections','Identify first communication gap','Assign follow-up drill'],'Timeline is evidence-based and ends with one owned action.','{"accuracy":25,"clarity":25,"timing":25,"follow_through":25}'::jsonb,array['squad','review'])
) as v(title,category,difficulty,role_tags,duration_minutes,objective,setup,steps,success_criteria,scoring_rubric,tags)
where not exists (select 1 from public.training_drills d where d.is_template=true and d.team_id is null and d.title=v.title);
